class Line {
  + Name
}

class Piece {
  + Type
  + Reference
  + SellingPrice
}

class Component {
  + Code
  + ManufacturingPrice
  + Type
}

class Store {
  + Address
  + FaxNumber
}

class Order {
  + OrderNumber
  + Date
}

class PieceComponent {
  + Quantity
}

class PieceOrder {
  + Quantity
}

Line "1" -- "*" Piece
Piece "*" -- "1" Line
Piece "1" -- "*" PieceComponent
PieceComponent "*" -- "1" Component
Component "*" -- "*" Piece
Component "*" -- "1" Component
Order "*" -- "1" Store
Order "*" -- "1" Piece
Order "1" -- "*" PieceOrder
Piece "1" -- "*" PieceOrder
PieceOrder "*" -- "1" Order

@enduml

